        r => parseJson[F, String]("String", r)
    }
  }

  override def postTruststorePKCS12(truststoreP12: Option[File] = None)(using auth: _Authorization.Basic): F[String] = {
    val requestHeaders = Seq(
      Some("Content-Type" -> "multipart/form-data")
    ).flatten
    val formParameters = Some((
      truststoreP12.map("truststore.p12" -> _).map(Seq(_))
    ).toSeq.flatten)

    _executeRequest[Unit, String](
      method = "POST",
      path = s"/etc/truststore",
      body = None,
      formParameters = formParameters,
      queryParameters = Nil,
      requestHeaders = requestHeaders,
      auth = Some(auth)) {
        r => parseJson[F, String]("String", r)
    }
  }

}


